def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return max(0.0, min(budget, 18.0))

    pressure_bids = []
    cindy_bid = None
    cindy_alive = False
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            pressure_bids.append(float(bid))
        if oid == 'Cindy':
            cindy_alive = True
            if bid is not None:
                cindy_bid = float(bid)

    tight_supply = supply <= 17.0
    medium_supply = supply <= 20.0
    critical = hp <= 3 or no_water >= 2
    urgent = hp <= 5 or no_water >= 1

    if cindy_alive:
        anchor = 99.0 if cindy_bid is None else cindy_bid
    elif pressure_bids:
        anchor = max(pressure_bids)
    else:
        anchor = 45.0

    if critical:
        bid = max(92.0, anchor + 3.0)
    elif tight_supply:
        bid = max(86.0, anchor - 4.0)
    elif urgent and medium_supply:
        bid = max(72.0, anchor - 12.0)
    elif urgent:
        bid = 58.0
    else:
        if cindy_alive:
            bid = 16.0 if supply >= 22.0 else 24.0
        else:
            bid = 28.0

    if day >= 8 and hp <= 6:
        bid = max(bid, 78.0)

    if budget <= 0:
        return 0.0

    reserve_floor = max(0.0, (10 - day) * 8.0)
    affordable = max(0.0, budget - reserve_floor)
    if critical:
        affordable = budget

    final_bid = min(budget, max(0.0, min(bid, max(affordable, 0.0))))

    if final_bid < 1.0 and budget >= 1.0:
        final_bid = 1.0

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    prev_bids = []
    prev_hp_after = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass
            try:
                prev_hp_after.append(float(prev.get('hp_after', 0.0)))
            except Exception:
                prev_hp_after.append(0.0)

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely to be scarce
    # Use a simple scarcity score from supply.
    scarcity = 0.0
    if supply <= MIN_SUPPLY:
        scarcity = 1.0
    elif supply >= MAX_SUPPLY:
        scarcity = 0.0
    else:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)

    # Base bid: aim to be competitive but not maxing out.
    # If yesterday saw high bids, increase slightly.
    base = DAILY_SALARY * (0.45 + 0.25 * scarcity)

    # If opponents were bidding very high yesterday, we must contest more.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * (0.55 + 0.25 * scarcity)

    # If my hp is low or I have accumulated no-water days, bid harder.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.85 + 0.1 * scarcity)
    elif my_hp <= 4.0:
        base = max(base, DAILY_SALARY * (0.65 + 0.1 * scarcity))

    # Convert base to a final bid with budget cap.
    bid = min(my_budget, base)

    # Add a small reactive bump when yesterday pressure was high.
    if highest_prev_bid > 0:
        bid = min(my_budget, bid + 0.1 * (highest_prev_bid - DAILY_SALARY * 0.5))

    # Ensure bid is non-negative.
    if bid < 0:
        bid = 0.0

    # If supply is very low, we may need to overpay to guarantee water.
    if supply <= float(WATER_REQ) + 2.0 and my_hp > 0.0:
        # push toward at least a strong fraction of salary
        bid = max(bid, min(my_budget, DAILY_SALARY * (0.6 + 0.2 * scarcity)))

    return float(bid)

